window.CA = {"date": "Tuesday, 07 July 2026", "updated": "2026-07-07 04:45", "updated_label": "07 Jul 2026, 04:45 IST", "items": [{"title": "PM Modi Begins Three-Nation Tour: Indonesia, New Zealand, and Australia", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi commenced a three-nation diplomatic visit beginning with Indonesia (Jakarta), followed by New Zealand and Australia. His aircraft was escorted by Indonesian fighter jets upon arrival in Jakarta. The agenda includes defence cooperation, critical minerals, and strategic partnership discussions. India is also reportedly eyeing a uranium supply pact with Australia during the visit.", "exam_angle": "Key for GS Paper 2 (IR): covers India's bilateral ties with ASEAN (Indonesia), Pacific nations, and the Quad partner Australia; also relevant for India's civil nuclear energy push and critical minerals diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Three nations: Indonesia, New Zealand, Australia", "Agenda: Defence, critical minerals, strategic ties", "India eyeing uranium supply pact with Australia", "Indonesia is India's key ASEAN partner; New Zealand PM Luxon called both 'natural partners'"], "source": "The Hindu / Hindustan Times / Times of India", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "NIA Charges Hafiz Saeed in Pahalgam Terror Attack Case", "category": "defence", "category_name": "Defence & Security", "summary": "India's National Investigation Agency (NIA) has filed charges against Pakistan-based Lashkar-e-Taiba chief Hafiz Saeed in connection with the Pahalgam terror attack case. The move marks a significant step in India's legal pursuit of designated terrorists based in Pakistan. Hafiz Saeed is already on the FATF-linked terrorism financing watchlist and is designated as a global terrorist by the UN.", "exam_angle": "Relevant for internal security and IR: NIA's mandate under the NIA Act 2008, India-Pakistan terrorism-related disputes, and India's counter-terror legal framework.", "gs_paper": "GS Paper 3 (Internal Security)", "key_facts": ["Agency: National Investigation Agency (NIA)", "Accused: Hafiz Saeed, LeT chief based in Pakistan", "Case: Pahalgam terror attack", "Saeed is a UN-designated global terrorist"], "source": "Times of India", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Pakistan's Bilawal Bhutto Threatens War Over Indus Waters Treaty", "category": "ir", "category_name": "International Relations", "summary": "Pakistan People's Party (PPP) leader Bilawal Bhutto Zardari threatened India with war, stating Pakistan is 'ready on all fronts' over the dispute regarding the Indus Waters Treaty (IWT). India had suspended the IWT in the aftermath of the Pahalgam terror attack. The Indus Waters Treaty, brokered by the World Bank in 1960, governs sharing of six Indus basin rivers between India and Pakistan.", "exam_angle": "Critical for GS Paper 2 (IR): Indus Waters Treaty provisions, India's suspension of IWT post-Pahalgam, and implications for India-Pakistan water diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Indus Waters Treaty signed: 1960, brokered by World Bank", "India suspended IWT following Pahalgam terror attack", "IWT allocates western rivers (Indus, Jhelum, Chenab) to Pakistan; eastern rivers to India", "Bilawal Bhutto is PPP chairman and former Pakistan Foreign Minister"], "source": "News18", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "New Zealand PM Christopher Luxon Addresses Khalistan Issue, Reaffirms India Ties", "category": "ir", "category_name": "International Relations", "summary": "New Zealand Prime Minister Christopher Luxon stated that the Khalistan issue 'caused suffering in India' and that New Zealand would not tolerate criminal behaviour or intimidation. He called India and New Zealand 'natural partners' ahead of PM Modi's visit to Wellington. Luxon's remarks are significant given concerns over Khalistani activities on New Zealand soil affecting bilateral relations.", "exam_angle": "Relevant for GS Paper 2 (IR): India's diaspora-related security concerns abroad, Five Eyes nations' stance on Sikh separatism, and India-New Zealand bilateral relations.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["NZ PM: Christopher Luxon", "Statement: Will not tolerate Khalistan-linked criminal behaviour", "Context: PM Modi's three-nation tour includes New Zealand", "India-NZ described as 'natural partners'"], "source": "News18 / Firstpost", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India Orders Meta to Remove Child Sexual Abuse Ads on Instagram", "category": "polity", "category_name": "Polity & Governance", "summary": "The Indian government directed Meta to remove advertisements on Instagram that were found to be promoting child sexual abuse material (CSAM). The order reflects India's growing regulatory assertiveness over social media intermediaries under the IT Act and IT Rules 2021. The action deepens Meta's regulatory challenges in India following previous content moderation controversies.", "exam_angle": "Relevant for GS Paper 2 (Governance): IT Act 2000, Intermediary Guidelines and Digital Media Ethics Code Rules 2021, and protection of children online (POCSO Act linkages).", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Platform: Instagram (Meta)", "Issue: Ads promoting child sexual abuse material (CSAM)", "Legal framework: IT Act 2000 and IT Rules 2021", "India is Meta's largest market by user base"], "source": "BBC / CNBC", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Hamas Dissolves Gaza Governing Body, Offers Transfer to UN/US-Backed Committee", "category": "ir", "category_name": "International Relations", "summary": "Hamas announced the dissolution of its governing body in Gaza, offering to transfer administrative authority to a UN and US-backed committee. Israel responded by demanding Hamas disarm, calling the move 'tricks.' The development comes amid ongoing ceasefire negotiations and international pressure for a post-war governance framework in Gaza.", "exam_angle": "Relevant for GS Paper 2 (IR): West Asia conflict dynamics, India's stated position of supporting a two-state solution, and UN-mediated governance frameworks.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Hamas dissolved its Gaza governing body (Political Bureau-linked administration)", "Transfer proposed to UN/US-backed committee", "Israel demands Hamas disarmament as precondition", "Context: Ongoing Israel-Gaza conflict post-October 2023"], "source": "The Hindu / Al Jazeera", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Khamenei Funeral: Trump Warns Iran — 'Will Finish the Job' If No Deal", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump issued a fresh warning to Iran amid the state funeral of Supreme Leader Ali Khamenei, saying the US will either make a nuclear deal with Iran or 'finish the job.' Iran's Embassy in India expressed gratitude to the Indian government for participating in Khamenei's funeral. The statements signal continued high tensions in the US-Iran nuclear standoff.", "exam_angle": "Relevant for GS Paper 2 (IR): Iran nuclear deal (JCPOA) history, India-Iran relations, Chabahar port strategic interest, and West Asia geopolitics.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Iran Supreme Leader Ali Khamenei's funeral held", "Trump: US will either make deal or 'finish the job'", "India represented at Khamenei's funeral (Iran Embassy expressed gratitude)", "Context: JCPOA negotiations remain stalled"], "source": "Hindustan Times / The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Extradition of Nirav Modi Imminent After Loss at European Court of Human Rights", "category": "polity", "category_name": "Polity & Governance", "summary": "Fugitive diamantaire Nirav Modi is expected to be extradited to India soon after losing his appeal at the European Court of Human Rights (ECHR). Nirav Modi is wanted in India in connection with the Punjab National Bank (PNB) fraud case estimated at over Rs 13,500 crore. He has been held in a UK prison while contesting extradition proceedings.", "exam_angle": "Relevant for GS Paper 2 (Polity/Governance) and GS Paper 3 (Economy): extradition treaties, India-UK bilateral legal cooperation, banking fraud, and fugitive economic offenders.", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Nirav Modi: Accused in PNB fraud (Rs 13,500+ crore)", "Court: European Court of Human Rights (ECHR) ruled against him", "Currently held in UK prison", "Relevant law: Fugitive Economic Offenders Act 2018"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Congress Challenges Meenakshi Natarajan's Rajya Sabha Nomination Rejection in High Court", "category": "polity", "category_name": "Polity & Governance", "summary": "The Indian National Congress has announced it will move the High Court challenging the rejection of its nominee Meenakshi Natarajan's Rajya Sabha nomination. The dispute raises questions about the constitutional process for Rajya Sabha elections and the role of the Election Commission in scrutinising nomination papers. Natarajan is a senior Congress leader from Madhya Pradesh.", "exam_angle": "Relevant for GS Paper 2 (Polity): Articles 80 and 84 on Rajya Sabha membership eligibility, nomination process, and judicial review of election matters.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Nominee: Meenakshi Natarajan (Congress, Madhya Pradesh)", "House: Rajya Sabha", "Action: Congress to approach High Court", "Relevant Articles: Article 80 (Rajya Sabha composition), Article 84 (qualification)"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Assam Rifles Soldiers Killed in Militant Ambush in Manipur's Ukhrul", "category": "defence", "category_name": "Defence & Security", "summary": "Two Assam Rifles personnel were killed and several others injured after militants ambushed a convoy in Ukhrul district of Manipur. The Assam Rifles, operating under the dual command of the Ministry of Home Affairs and the Indian Army, is the oldest paramilitary force of India. Manipur has seen sustained ethnic violence and insurgency since May 2023.", "exam_angle": "Relevant for GS Paper 3 (Internal Security): Assam Rifles' mandate under AFSPA, insurgency in Northeast India, and the ongoing Manipur conflict situation.", "gs_paper": "GS Paper 3 (Internal Security)", "key_facts": ["Force: Assam Rifles (oldest paramilitary, dual control: MHA + Army)", "Location: Ukhrul district, Manipur", "Casualties: 2 soldiers killed, several injured", "Context: Manipur ethnic violence ongoing since May 2023"], "source": "Times of India / NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "NSE Targets Rs 30,000 Crore IPO Launch in September", "category": "economy", "category_name": "Economy & Banking", "summary": "The National Stock Exchange (NSE) has set a target to launch its Initial Public Offering (IPO) worth Rs 30,000 crore in September. NSE's IPO has been long-awaited pending SEBI clearance following the co-location scam investigations. NSE is the world's largest derivatives exchange by volume and India's largest equity exchange.", "exam_angle": "Relevant for GS Paper 3 (Economy): capital markets regulation, SEBI's role, IPO process, and the significance of NSE's listing for market deepening.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["NSE IPO target size: Rs 30,000 crore", "Target launch: September", "NSE: world's largest derivatives exchange by volume", "Regulator: SEBI clearance pending due to co-location scam probe"], "source": "The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India's Trade Deficit with Japan Triples in 10 Years; FTA Review Underway", "category": "economy", "category_name": "Economy & Banking", "summary": "India's trade deficit with Japan has tripled over the past decade, raising concerns about the effectiveness of the India-Japan Comprehensive Economic Partnership Agreement (CEPA) signed in 2011. A review of the Free Trade Agreement (FTA) is currently underway to rebalance trade flows and attract greater Japanese investment into India. Japan is a key investor in India's infrastructure and automobile sectors.", "exam_angle": "Relevant for GS Paper 3 (Economy) and GS Paper 2 (IR): India-Japan CEPA, trade deficit management, and the broader debate on India's FTA outcomes.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India-Japan CEPA signed: 2011", "Trade deficit with Japan tripled in 10 years", "FTA review ongoing to boost investments", "Japan is a major investor in Indian infrastructure and automobile sector"], "source": "The New Indian Express", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "World Bank Updates Income Classification: Vietnam and 5 Others Move Up; India's Status", "category": "reports", "category_name": "Reports & Indices", "summary": "The World Bank released its updated income classification of countries, with Vietnam and five other nations climbing to higher income brackets. India continues to be classified as a lower-middle-income country in the World Bank's groupings based on Gross National Income (GNI) per capita. The World Bank uses the Atlas method for GNI per capita calculation to classify countries annually.", "exam_angle": "Relevant for GS Paper 3 (Economy): World Bank income classification thresholds (low, lower-middle, upper-middle, high income), India's per capita income position, and development benchmarks.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["World Bank classifies countries by GNI per capita (Atlas method)", "Vietnam among 6 nations moving up in income classification", "India remains: lower-middle-income country", "Four income groups: Low, Lower-middle, Upper-middle, High income"], "source": "India Today", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "UP Cabinet Approves Startup Policy 2026 with Rs 15 Lakh Seed Funding", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "The Uttar Pradesh Cabinet approved the Startup Policy 2026, which includes a provision of Rs 15 lakh seed funding for new ventures. The policy aims to boost the startup ecosystem in India's most populous state by providing financial and regulatory support to early-stage entrepreneurs. UP is targeting to become a top startup destination to compete with states like Maharashtra, Karnataka and Telangana.", "exam_angle": "Relevant for GS Paper 3 (Economy/Schemes): state-level startup ecosystem policies, seed funding mechanisms, and India's overall startup promotion framework (Startup India).", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Policy: UP Startup Policy 2026", "Approved by: Uttar Pradesh Cabinet", "Key provision: Rs 15 lakh seed funding per new venture", "Complements Central Government's Startup India initiative (launched 2016)"], "source": "News18", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Hyderabad Startup Prepares for World's First Soft Robotic Orbital Capture Demonstration", "category": "scitech", "category_name": "Science & Technology", "summary": "A Hyderabad-based startup is preparing to conduct the world's first demonstration of soft robotic capture technology in Earth's orbit. The mission is aimed at addressing the growing problem of space debris by using flexible, soft robotic systems to capture defunct satellites and debris. This positions India's private space sector at the frontier of in-orbit servicing and debris mitigation technology.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech): India's private space sector under IN-SPACe framework, space debris mitigation, and active debris removal (ADR) technologies.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Startup based in Hyderabad, India", "Mission: World's first soft robotic capture demonstration in orbit", "Purpose: Space debris mitigation / active debris removal", "Regulatory body: IN-SPACe (Indian National Space Promotion and Authorisation Centre)"], "source": "Deccan Herald", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India's Power Demand to Grow 6% Annually Over Next 4-5 Years: Centrum Report", "category": "reports", "category_name": "Reports & Indices", "summary": "A report by Centrum Research projects that India's power demand will grow at approximately 6% annually over the next four to five years. The growth is expected to be driven by rapid industrialisation, rising urban demand, electric vehicle adoption, and data centre proliferation. India is currently the third-largest electricity producer and consumer in the world.", "exam_angle": "Relevant for GS Paper 3 (Economy/Energy): India's energy security, power sector reforms, renewable energy targets, and the PM Surya Ghar and National Electricity Plan 2032 context.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Projected power demand growth: ~6% per annum", "Period: Next 4-5 years", "Report by: Centrum Research", "India: 3rd largest electricity producer and consumer globally"], "source": "Times of India", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Sonam Wangchuk's Hunger Strike Enters Day 9 Over Ladakh Statehood Demand", "category": "polity", "category_name": "Polity & Governance", "summary": "Climate activist and Magsaysay Award winner Sonam Wangchuk's hunger strike entered its ninth day as he continues to demand full statehood and Sixth Schedule protections for the Union Territory of Ladakh. Wangchuk has previously led the 'Leh Chalo' march and has been a prominent voice for protecting the tribal and ecological rights of Ladakh's indigenous communities. Ladakh became a Union Territory without a legislature on 31 October 2019 following the reorganisation of Jammu & Kashmir.", "exam_angle": "Relevant for GS Paper 2 (Polity): Sixth Schedule of the Constitution (tribal area protection), UT governance without legislature, Article 3 (reorganisation of states), and Ladakh's political status.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Activist: Sonam Wangchuk (Ramon Magsaysay Award winner)", "Demand: Statehood and Sixth Schedule protection for Ladakh", "Ladakh became UT (without legislature) on 31 October 2019", "Sixth Schedule applies to tribal areas in NE India; Ladakh seeks its inclusion"], "source": "Times of India", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Venezuela Earthquake Death Toll Rises to 3,535 — Places in News", "category": "places", "category_name": "Places in News", "summary": "The death toll from a major earthquake in Venezuela has risen to 3,535, with over 16,700 people reported injured. Venezuela, located in northern South America, lies on the Caribbean tectonic plate boundary, making it seismically active. The disaster has triggered international humanitarian response calls.", "exam_angle": "Relevant for GS Paper 1 (Geography): seismic zones of South America, Caribbean plate tectonics, and disaster management frameworks. Also useful for 'places in news' questions.", "gs_paper": "GS Paper 1 (Geography)", "key_facts": ["Country: Venezuela (northern South America)", "Death toll: 3,535; Injured: 16,700+", "Cause: Major earthquake", "Venezuela sits on Caribbean-South American plate boundary"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Xi Jinping Confirmed to Visit United States in September: Trump", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump announced that Chinese President Xi Jinping is scheduled to visit the United States in September. The visit is expected to cover ongoing US-China trade tensions, tariff negotiations, and broader geopolitical disputes including Taiwan, South China Sea, and technology competition. The announcement comes amid a period of cautious diplomatic re-engagement after earlier tariff escalations.", "exam_angle": "Relevant for GS Paper 2 (IR): US-China relations, trade war dynamics, implications for India's strategic positioning in the Indo-Pacific, and Quad context.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Xi Jinping to visit USA in September (per Trump announcement)", "Agenda: Trade, tariffs, geopolitical issues", "Context: Ongoing US-China trade tensions and tariff war", "Significant for Indo-Pacific balance of power"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Netanyahu Asks US Not to Sell F-35 Jets to Turkey Over Regional Power Balance", "category": "defence", "category_name": "Defence & Security", "summary": "Israeli Prime Minister Benjamin Netanyahu has formally requested the United States not to sell F-35 stealth fighter jets to Turkey, citing concerns over the regional 'power balance.' Turkey was previously removed from the F-35 programme in 2019 after purchasing Russia's S-400 missile defence system. The development reflects ongoing tensions within NATO over Turkey's strategic alignments.", "exam_angle": "Relevant for GS Paper 2 (IR) and GS Paper 3 (Defence): F-35 technology transfer politics, NATO cohesion, US arms export policy (ITAR), and Israel-Turkey-US triangle.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["F-35: 5th-generation stealth multirole fighter (Lockheed Martin, USA)", "Turkey excluded from F-35 programme in 2019 due to S-400 purchase from Russia", "Netanyahu's request: Block F-35 sale to Turkey", "Concern: Regional power balance in Middle East/Eastern Mediterranean"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India-UK Free Trade Agreement Set for July 15 Rollout; Industry Welcomes Pact", "category": "ir", "category_name": "International Relations", "summary": "The India-UK Free Trade Agreement (FTA) is scheduled to come into effect on July 15, 2026, sparking significant industry optimism. The pact covers goods, services, and investment, and is expected to boost bilateral trade substantially. It is one of the most comprehensive trade deals India has signed in recent years, covering sectors including pharmaceuticals, textiles, professional services, and digital trade.", "exam_angle": "India's bilateral trade agreements are a recurring GS Paper 2 (IR) and GS Paper 3 (Economy) topic; aspirants should know key provisions, sectors covered, and strategic significance of the India-UK FTA.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-UK FTA rollout date: July 15, 2026", "Covers goods, services, investment, and digital trade", "One of India's most comprehensive bilateral trade deals", "Sectors benefiting: pharmaceuticals, textiles, professional services"], "source": "India Today", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India Lifts Gas Supply Curbs Imposed During Strait of Hormuz Disruption as LNG Supply Resumes", "category": "economy", "category_name": "Economy & Banking", "summary": "India lifted emergency gas supply restrictions that were imposed during a period of disruption to shipping through the Strait of Hormuz. The government confirmed that 15 India-bound ships carrying urea, DAP (diammonium phosphate), and sulphur had successfully crossed the Hormuz Strait. The Hormuz Strait is critical to India's energy security, as a significant share of India's crude oil and LNG imports transit through it. The lifting of curbs signals normalisation of supply chains.", "exam_angle": "The Strait of Hormuz is strategically vital for India's energy imports; this event connects to India's energy security, import dependency, and West Asia geopolitics — all frequent exam themes.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["15 India-bound ships carrying urea, DAP, sulphur crossed Hormuz", "India lifted gas supply curbs imposed during Hormuz disruption", "LNG and fertiliser supply chains now normalised", "Strait of Hormuz: critical chokepoint for India's oil and gas imports"], "source": "The Quint / The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India and Russia Set $50 Billion Bilateral Investment Target by 2030", "category": "ir", "category_name": "International Relations", "summary": "India and Russia have agreed to set a bilateral investment target of $50 billion by 2030, deepening economic engagement between the two countries. This comes amid continued strategic partnership even as Russia faces Western sanctions over the Ukraine conflict. The investment push covers sectors such as energy, defence, fertilisers, and infrastructure. India-Russia trade has surged in recent years, particularly in crude oil imports.", "exam_angle": "India-Russia economic ties, especially amid Western sanctions and India's strategic autonomy doctrine, are highly relevant for GS Paper 2 (IR) and GS Paper 3 (Economy).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Russia bilateral investment target: $50 billion by 2030", "Sectors: energy, defence, fertilisers, infrastructure", "India-Russia trade has expanded significantly due to crude oil imports post-2022", "Russia remains a key defence supplier and strategic partner for India"], "source": "The Economic Times", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "EAM Jaishankar on 4-Nation Diplomatic Tour; Meets Qatar PM on Energy and West Asia", "category": "ir", "category_name": "International Relations", "summary": "External Affairs Minister S. Jaishankar undertook a 4-nation diplomatic tour, which included a meeting with the Prime Minister of Qatar to review bilateral energy ties, trade relations, and the situation in West Asia. Qatar is one of India's largest suppliers of LNG and is home to a large Indian diaspora. The visit comes amid heightened tensions in the region following the death of Iranian Supreme Leader Ali Khamenei.", "exam_angle": "India's West Asia diplomacy, energy security (LNG from Qatar), and diaspora engagement are key GS Paper 2 (IR) topics; EAM Jaishankar's tours frequently appear in current affairs.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["EAM Jaishankar undertook a 4-nation diplomatic tour", "Met Qatar PM to review energy, trade, and West Asia situation", "Qatar is a major LNG supplier to India", "Visit coincides with regional tensions post-Khamenei death"], "source": "India Today", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Netanyahu Cites India's Support After JD Vance Calls US 'Only Ally' of Israel", "category": "ir", "category_name": "International Relations", "summary": "Israeli Prime Minister Benjamin Netanyahu pushed back against US Vice President JD Vance's claim that the US was Israel's 'only ally,' explicitly citing India and its 1.4 billion people as friends of Israel. This public statement highlights the growing perception of India-Israel strategic closeness even as India has maintained a formal stance supporting the two-state solution. The remark drew significant attention to the nature of India's foreign policy balancing act.", "exam_angle": "India-Israel relations, India's West Asia policy, and India's strategic autonomy (maintaining ties with both Israel and Arab/Palestinian sides) are key GS Paper 2 (IR) themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Netanyahu cited India ('1.4 billion Indians') as supporters of Israel", "JD Vance had called the US Israel's 'only ally'", "India officially supports the two-state solution for Palestine", "India-Israel defence and technology ties have deepened since 2017"], "source": "NDTV / News18", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "PM Modi's Indonesia Visit to Focus on UPI, Defence, and Digital Public Infrastructure Partnership", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi's upcoming visit to Indonesia is set to focus on expanding UPI (Unified Payments Interface) adoption, defence cooperation, and digital public infrastructure (DPI) partnerships. Indonesia is one of the largest economies in Southeast Asia and an important partner in ASEAN. India has been actively promoting its DPI stack — including UPI, Aadhaar, and DigiLocker — as a global model for digital governance.", "exam_angle": "India's Act East Policy, UPI's global expansion, and DPI diplomacy are central to GS Paper 2 (IR) and GS Paper 3 (Sci-Tech/Economy); Indonesia is a key ASEAN partner.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Modi's Indonesia visit agenda: UPI expansion, defence, Digital Public Infrastructure", "Indonesia is a key ASEAN and G20 partner for India", "India's DPI stack (UPI, Aadhaar, DigiLocker) being promoted globally", "UPI now operational in several countries through bilateral MoUs"], "source": "NDTV Profit", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Trump to Meet Zelensky and Syrian President at NATO Summit in Turkey", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump is scheduled to meet Ukrainian President Zelensky and Syria's new President at the upcoming NATO Summit to be held in Turkey. Trump also held a 'businesslike' phone call with Russian President Putin, offering again to facilitate a ceasefire in Ukraine. The NATO summit in Turkey is significant as it brings together key actors in the ongoing conflicts in both Ukraine and West Asia.", "exam_angle": "NATO's evolving role, US-Russia-Ukraine conflict dynamics, and Turkey's strategic positioning within NATO are important GS Paper 2 (IR) themes for Prelims and Mains.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["NATO Summit venue: Turkey", "Trump to meet Zelensky and Syrian President at the summit", "Trump-Putin call described as 'businesslike'; US offered mediation on Ukraine", "Russia claimed it captured Kostiantynivka town; Ukraine disputed the claim"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Iran Seeks Tighter Control Over Strait of Hormuz Following Khamenei's Death", "category": "ir", "category_name": "International Relations", "summary": "Following the death of Iranian Supreme Leader Ali Khamenei, Iran has signalled intentions to tighten its control over the Strait of Hormuz, a critical global oil and gas chokepoint. The US reportedly pressured countries to reduce participation at Khamenei's funeral, with at least 13 nations withdrawing or reducing their delegations. Khamenei's son Mojtaba, widely seen as a potential successor, notably skipped the funeral. The post-Khamenei succession dynamics could significantly affect regional stability.", "exam_angle": "The Strait of Hormuz is the world's most critical oil chokepoint; Iran's leadership transition has major implications for India's energy security, West Asia stability, and global oil markets.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Ali Khamenei was Iran's Supreme Leader; died recently", "Mojtaba Khamenei is considered the likely successor but skipped the funeral", "Strait of Hormuz: ~20% of global oil trade passes through it", "US pressured at least 13 nations to reduce participation at Khamenei's funeral"], "source": "NDTV / The Guardian", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Ethanol Blending (E20) Programme Faces Pushback from Motorists Over Mileage Concerns", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "India's ethanol blending programme — which mandates E20 fuel (20% ethanol blended with petrol) — is facing public resistance from motorists citing reduced fuel efficiency (mileage loss) and engine compatibility concerns. Oil companies and the auto industry have defended the safety and viability of E20, while the government maintains the programme is essential for energy security and reducing carbon emissions. The E20 target is part of India's National Biofuel Policy 2018.", "exam_angle": "India's biofuel/ethanol blending programme is directly linked to energy security, agriculture (sugarcane/maize as feedstock), and climate commitments — a cross-cutting GS Paper 3 topic.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["E20: petrol blended with 20% ethanol; mandated under National Biofuel Policy 2018", "India's ethanol blending target: 20% by 2025-26", "Concerns: reduced mileage, engine compatibility for older vehicles", "Ethanol feedstock: sugarcane, maize, food grain surplus"], "source": "Bloomberg / The Indian Express", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Centre Cracks Down on Instagram Over Child Sexual Abuse Content; Orders Immediate Ad Suspension", "category": "polity", "category_name": "Polity & Governance", "summary": "The Central Government has issued a stern notice to Instagram, ordering it to immediately stop running advertisements and demanding a response over the platform's failure to curb child sexual abuse material (CSAM) content. The Ministry of Electronics and Information Technology (MeitY) is the nodal authority for regulating digital intermediaries in India under the IT Act 2000 and IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021. This action reflects increasing government scrutiny of Big Tech platforms.", "exam_angle": "Digital regulation of social media intermediaries under IT Rules 2021, CSAM as a legal issue, and MeitY's regulatory role are highly relevant for GS Paper 2 (Polity/Governance) and GS Paper 3 (Sci-Tech).", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Government ordered Instagram to stop ads over CSAM content", "Nodal authority: MeitY (Ministry of Electronics and IT)", "Governing law: IT Act 2000 + IT (Intermediary Guidelines) Rules 2021", "Intermediaries must act on CSAM within 24 hours under IT Rules 2021"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Passport Ranking Slips; Remains Outside Top 100 on Global Passport Index", "category": "reports", "category_name": "Reports & Indices", "summary": "India's passport ranking has fallen further, remaining outside the top 100 on the latest global passport power index. The Henley Passport Index ranks passports by the number of visa-free or visa-on-arrival destinations accessible. India's passport provides access to a limited number of countries without prior visa, reflecting the relatively restricted global mobility of Indian passport holders compared to top-ranked nations.", "exam_angle": "Passport indices and India's global standing on such indices are frequently tested in Prelims; connects to bilateral visa agreements, diplomatic relations, and soft power.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India's passport ranking: outside top 100 (Henley Passport Index 2026)", "Henley Passport Index ranks by number of visa-free/on-arrival destinations", "Top-ranked passports (2026): typically Singapore, Japan, Germany, France", "India's passport grants visa-free access to approximately 58-62 countries"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Army Corners Two Lashkar-e-Taiba Terrorists in J&K's Shopian; Counter-Terror Operation Underway", "category": "defence", "category_name": "Defence & Security", "summary": "The Indian Army launched a counter-terrorism operation in the Shopian district of Jammu & Kashmir after surveillance cameras detected two local Lashkar-e-Taiba (LeT) militants in an orchard. The Army plugged escape routes and cordoned off the area. Operations in Shopian are part of ongoing counter-insurgency efforts in the Kashmir Valley, where LeT remains one of the most active proscribed terrorist organisations.", "exam_angle": "Counter-terror operations in J&K, Lashkar-e-Taiba's designation as a terrorist organisation, and India's security architecture in J&K are key defence and internal security topics for GS Paper 3.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Location: Shopian district, Jammu & Kashmir", "Group: Lashkar-e-Taiba (LeT) — UN-designated terrorist organisation", "Army used surveillance cameras to detect militants", "LeT is based in Pakistan; banned under UAPA in India"], "source": "The Times of India / NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Indian Naval Ships Conclude Successful Visit to Singapore, Deepening Maritime Ties", "category": "defence", "category_name": "Defence & Security", "summary": "Indian Naval ships concluded a successful port visit to Singapore as part of ongoing efforts to strengthen maritime cooperation in the Indo-Pacific region. India and Singapore have robust defence ties, including regular bilateral naval exercises such as SIMBEX (Singapore-India Maritime Bilateral Exercise). Singapore is a key partner in India's Act East Policy and plays an important role in the strategic Malacca Strait region.", "exam_angle": "India's maritime diplomacy, Act East Policy, Indo-Pacific strategy, and India-Singapore defence relations are recurring GS Paper 2 (IR) and GS Paper 3 (Defence) themes.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Indian Naval ships completed a port visit to Singapore", "India-Singapore bilateral naval exercise: SIMBEX (held annually)", "Singapore is a key partner in India's Act East Policy", "Malacca Strait: strategic chokepoint near Singapore critical for India's trade"], "source": "PIB", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "NFDC-NFAI's 4K Restoration of 'Oka Oorie Katha' Makes World Premiere at 60th Karlovy Vary International Film Festival", "category": "culture", "category_name": "Art & Culture", "summary": "The National Film Development Corporation (NFDC) and National Film Archive of India (NFAI) jointly restored the 1977 Telugu classic 'Oka Oorie Katha' (directed by Mrinal Sen) in 4K and premiered it at the 60th Karlovy Vary International Film Festival in the Czech Republic. This is part of India's film heritage preservation initiative. NFAI, under MIB, is responsible for preserving and restoring India's cinematic heritage.", "exam_angle": "Film heritage conservation by NFDC/NFAI and India's cultural diplomacy through film festivals are relevant for GS Paper 1 (Culture) and GS Paper 2 (Governance/Soft Power).", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Film: 'Oka Oorie Katha' (1977 Telugu film, dir. Mrinal Sen)", "Restored in 4K by NFDC and NFAI jointly", "World Premiere: 60th Karlovy Vary International Film Festival, Czech Republic", "NFAI (National Film Archive of India) is under Ministry of Information & Broadcasting"], "source": "PIB", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Meghalaya's South Garo Hills Records Zero Maternal Deaths for Eight Consecutive Months", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "South Garo Hills district in Meghalaya has achieved zero maternal deaths for eight consecutive months, a remarkable public health milestone for a region that had historically recorded high maternal mortality. This achievement is attributed to improved institutional deliveries, better ANM (Auxiliary Nurse Midwife) coverage, and effective implementation of centrally sponsored schemes such as Janani Suraksha Yojana (JSY) and the POSHAN Abhiyaan. Meghalaya's MMR had been one of the higher ones among northeastern states.", "exam_angle": "Maternal Mortality Rate (MMR) reduction, Janani Suraksha Yojana, and healthcare delivery in northeastern states are key GS Paper 2 (Governance/Social Justice) topics.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["South Garo Hills, Meghalaya: zero maternal deaths for 8 consecutive months", "Key schemes driving this: Janani Suraksha Yojana (JSY), POSHAN Abhiyaan", "India's target MMR: below 70 per lakh live births (SDG target: below 70 by 2030)", "India's national MMR has declined significantly over the past decade"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India Needs Second Home for Asiatic Lions: Conservation Experts", "category": "environment", "category_name": "Environment & Ecology", "summary": "Conservation experts and reports have reiterated the urgency of establishing a second home for the Asiatic lion (Panthera leo persica), currently found exclusively in the Gir National Park and Wildlife Sanctuary in Gujarat. The Supreme Court had earlier directed the central government to relocate some lions to Kuno-Palpur National Park in Madhya Pradesh. The single-population vulnerability makes Asiatic lions susceptible to extinction from disease outbreaks or natural disasters.", "exam_angle": "Asiatic lion conservation, Project Lion, Gir National Park, the Supreme Court's Kuno-Palpur relocation order, and biodiversity protection connect to GS Paper 3 (Environment) and GS Paper 2 (Polity/Judiciary).", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Asiatic Lion (Panthera leo persica): found only in Gir, Gujarat — IUCN: Endangered", "Supreme Court directed relocation of some lions to Kuno-Palpur NP, Madhya Pradesh", "Current Asiatic lion population: approximately 674 (2020 census)", "Project Lion launched in 2020 to protect and increase lion population"], "source": "The Hindu", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Top IT Firms Face Muted Q1 Results as AI Spending Fails to Translate into Revenue Growth", "category": "economy", "category_name": "Economy & Banking", "summary": "A report projects that India's top IT companies — including TCS, Infosys, Wipro, and HCL Technologies — are set for subdued Q1 FY27 results despite heavy AI-related spending by global clients. The disconnect between AI investment and actual IT services revenue growth reflects a transition period where AI tools are being implemented but have not yet generated large-scale outsourcing contracts. TCS Q1 results are among the key events watched in the week ahead.", "exam_angle": "India's IT sector performance, the impact of AI on outsourcing, and India's services exports are relevant for GS Paper 3 (Economy); IT sector is a major contributor to India's GDP and foreign exchange earnings.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's IT sector: contributes ~7.5% of GDP and ~50% of service exports", "Top IT firms: TCS, Infosys, Wipro, HCL Technologies, Tech Mahindra", "Muted Q1 FY27 growth attributed to slower discretionary spending globally", "AI adoption is disrupting traditional IT outsourcing models"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Drone Delivery Ecosystem Expands in India Amid Regulatory Push for Last-Mile Solutions", "category": "scitech", "category_name": "Science & Technology", "summary": "India's drone delivery sector is witnessing rapid expansion, with multiple startups and logistics companies testing drone-based last-mile delivery in healthcare (medicines, vaccines), e-commerce, and agriculture. The Drone Rules 2021 and the PLI scheme for drones have provided regulatory clarity and financial incentives. The government's 'Drone Shakti' initiative under the Union Budget 2022-23 aims to make India a global drone hub.", "exam_angle": "Drone policy (Drone Rules 2021, PLI for drones, Drone Shakti), DGCA's regulatory role, and drone applications in healthcare and logistics are frequently tested in GS Paper 3 (Sci-Tech).", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Drone Rules 2021 provide regulatory framework for civilian drone operations in India", "PLI Scheme for Drones: approved with Rs 120 crore outlay", "'Drone Shakti' initiative announced in Union Budget 2022-23", "DGCA is the nodal authority for drone regulation in India"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "ISRO's Gaganyaan Parachute Test Vehicle Clears First Ground Test", "category": "scitech", "category_name": "Science & Technology", "summary": "ISRO's parachute test vehicle for the Gaganyaan human spaceflight mission has successfully cleared its first ground test, marking a critical milestone in crew recovery system validation. The parachute system is essential for the safe deceleration and landing of the crew module during re-entry. This test is part of a series of qualification tests being conducted before the crewed mission. Gaganyaan is India's first indigenous human spaceflight programme.", "exam_angle": "Gaganyaan is a flagship ISRO mission frequently tested in UPSC; questions arise on mission components, test vehicles (TV-D1, etc.), and India's space milestones. Connects to GS Paper 3 Science & Technology.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Mission: Gaganyaan — India's first human spaceflight programme", "Test: Parachute Test Vehicle (PTV) first ground test cleared", "Purpose: Validates crew module deceleration and safe landing system", "Implementing agency: ISRO"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "CG Semi OSAT Semiconductor Facility Inaugurated at Sanand, Gujarat", "category": "scitech", "category_name": "Science & Technology", "summary": "Union Minister Ashwini Vaishnaw inaugurated the CG Semi OSAT (Outsourced Semiconductor Assembly and Test) facility at Sanand, Gujarat, describing it as a historic milestone in India's semiconductor journey. The facility is part of India's broader push to establish a domestic semiconductor ecosystem under the India Semiconductor Mission. Sanand in Gujarat has emerged as a key hub for India's semiconductor manufacturing ambitions. The inauguration signals progress in reducing India's dependence on semiconductor imports.", "exam_angle": "India's semiconductor policy and the India Semiconductor Mission are high-priority UPSC topics connecting to GS3 (Technology, Economy). OSAT facilities are a key part of the semiconductor value chain.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Facility: CG Semi OSAT (Outsourced Semiconductor Assembly and Test)", "Location: Sanand, Gujarat", "Inaugurated by: Union Minister Ashwini Vaishnaw", "Context: Part of India Semiconductor Mission to build domestic chip ecosystem"], "source": "PIB", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "MHA Designates 17 Pakistanis and 6 Indians as 'Individual Terrorists' Under UAPA", "category": "polity", "category_name": "Polity & Governance", "summary": "The Ministry of Home Affairs (MHA) has designated 17 individuals from Pakistan and 6 Indian nationals as 'individual terrorists' under the Unlawful Activities (Prevention) Act (UAPA). This move is part of India's ongoing counter-terrorism framework following the Pahalgam terror attack and Operation Sindoor. The designation under UAPA allows authorities to impose financial restrictions and other punitive measures on listed individuals. This is a significant use of India's anti-terror legal architecture.", "exam_angle": "UAPA provisions for designating individual terrorists (Section 35/Schedule 4) are directly relevant for GS Paper 2 (Polity/Internal Security). Tests knowledge of India's counter-terrorism legal framework.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Designated by: Ministry of Home Affairs (MHA)", "Numbers: 17 Pakistani nationals + 6 Indian nationals tagged as individual terrorists", "Law invoked: UAPA (Unlawful Activities Prevention Act)", "Significance: Part of post-Pahalgam/Operation Sindoor counter-terror measures"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Anti-Terror Operation Launched in J&K's Shopian; Two LeT Terrorists Detected via Camera", "category": "defence", "category_name": "Defence & Security", "summary": "Security forces launched a major anti-terror operation in Shopian district of Jammu & Kashmir after surveillance cameras detected the presence of two Lashkar-e-Taiba (LeT) terrorists in an orchard. The Army plugged escape routes around the location as the search entered its second day. Shopian has historically been a hotspot for militant activity in the Kashmir Valley. The operation reflects the ongoing counter-insurgency operations in J&K using modern surveillance technology.", "exam_angle": "Counter-terrorism operations in J&K, the role of technology in internal security, and the threat posed by Pakistan-based groups like LeT are recurring UPSC themes under Internal Security (GS Paper 3).", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Location: Shopian district, Jammu & Kashmir", "Group involved: Lashkar-e-Taiba (LeT)", "Method: Surveillance camera detection of terrorists in orchard", "Operation: Army cordoned area and plugged escape routes"], "source": "NDTV", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "PM Modi's Indonesia Visit Aims to Deepen India's Strategic Partnership with ASEAN's Largest Economy", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi visited Indonesia to strengthen one of India's most significant strategic partnerships in the Indo-Pacific region. Indonesia, as ASEAN's largest economy and a key maritime nation, holds strategic importance for India's Act East Policy and Indo-Pacific vision. The visit is expected to cover defence cooperation, trade, connectivity, and digital economy ties. India-Indonesia relations have been elevated to a Comprehensive Strategic Partnership.", "exam_angle": "India-Indonesia relations, Act East Policy, and ASEAN engagement are standard GS Paper 2 (IR) topics. Indonesia's strategic location in the Indo-Pacific and its role in India's maritime strategy are exam-relevant.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["PM Modi visited Indonesia to strengthen bilateral strategic partnership", "India-Indonesia relationship: Comprehensive Strategic Partnership", "Indonesia: ASEAN's largest economy; strategically located in Indo-Pacific", "Key policy context: India's Act East Policy and Indo-Pacific vision"], "source": "Hindustan Times", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "India's Three Senior Ministers Head to Brussels for India-EU Trade Mission", "category": "ir", "category_name": "International Relations", "summary": "Three senior Indian ministers travelled to Brussels to advance trade negotiations and economic ties with the European Union. Commerce Minister Piyush Goyal also provided updates on the status of trade talks with Canada, Israel, and Peru, indicating a broad-based push to conclude pending FTAs. The India-EU trade talks have been ongoing for several years after being revived in 2022. The Brussels mission signals India's renewed push to diversify its trade partnerships amid global realignments.", "exam_angle": "India-EU FTA negotiations and India's broader FTA strategy are recurring GS Paper 2 (IR) and GS Paper 3 (Economy) topics. The involvement of multiple ministers underscores the diplomatic priority accorded to trade deals.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Destination: Brussels (EU headquarters)", "Led by: Commerce Minister Piyush Goyal (and two other senior ministers)", "Also discussed: Trade talks with Canada, Israel, and Peru", "Context: India's push to advance India-EU FTA negotiations"], "source": "The Economic Times", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Government Fact-Checks Reports of Bhutan Rejecting India's E20 Petrol Offer", "category": "ir", "category_name": "International Relations", "summary": "The Indian government issued a fact-check disputing media reports that Bhutan had rejected India's offer of E20 petrol (petrol blended with 20% ethanol). The government clarified the actual status of discussions on ethanol-blended fuel exports to the neighbouring nation. E20 fuel is part of India's National Biofuel Policy to promote ethanol blending and reduce oil import dependence. India-Bhutan energy ties are a significant aspect of the bilateral relationship.", "exam_angle": "India's ethanol blending programme (National Biofuel Policy), E20 fuel targets, and India-Bhutan special relations are important for GS Paper 3 (Economy/Energy) and GS Paper 2 (IR). Tests awareness of energy diplomacy.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["E20 petrol: Petrol blended with 20% ethanol under India's National Biofuel Policy", "Government issued official fact-check on Bhutan rejection reports", "India-Bhutan: Special bilateral relationship with close energy/trade linkages", "Context: India's ethanol blending programme targets reducing oil import dependency"], "source": "India Today", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "India's Passport Ranking Slips, Remains Outside Global Top 100", "category": "reports", "category_name": "Reports & Indices", "summary": "India's passport ranking has slipped in the latest Henley Passport Index, with the country remaining outside the global top 100. The Henley Passport Index ranks passports based on the number of destinations accessible visa-free or with visa-on-arrival. Japan, Singapore, and several European nations traditionally dominate the top positions. India's lower ranking reflects limited visa-free access for Indian passport holders across major destinations.", "exam_angle": "Passport indices (Henley, Arton) are standard current affairs for UPSC. India's soft power, visa diplomacy, and international standing are GS Paper 2 themes. The top-ranked countries are frequently asked in prelims.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Index: Henley Passport Index (ranks passports by visa-free access)", "India's status: Outside global top 100, ranking has slipped", "Top-ranked passports: Japan, Singapore, and European nations traditionally lead", "Criteria: Number of destinations accessible visa-free or visa-on-arrival"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Ministry of Road Transport to Introduce Cybersecurity and Software Update Norms for Smart Vehicles", "category": "polity", "category_name": "Polity & Governance", "summary": "The Ministry of Road Transport and Highways (MoRTH) announced plans to introduce new regulations on cybersecurity and software update management for increasingly connected and smart vehicles. As vehicles integrate more software-driven systems, cybersecurity vulnerabilities pose risks of remote hijacking and data breaches. The new norms will align India with international standards such as UNECE WP.29 regulations on vehicle cybersecurity. This is part of India's broader effort to regulate the automotive technology ecosystem.", "exam_angle": "Regulation of emerging technologies (connected vehicles, cybersecurity) falls under GS Paper 3 (Sci-Tech/Economy). MoRTH's regulatory role and India's alignment with international vehicle safety standards are exam-relevant.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Ministry: Ministry of Road Transport and Highways (MoRTH)", "New laws: Cybersecurity and software update management for smart/connected vehicles", "Risk addressed: Remote vehicle hijacking and software vulnerabilities", "International alignment: Similar to UNECE WP.29 vehicle cybersecurity regulations"], "source": "The Economic Times", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Centre Issues Crackdown Notice to Instagram Over Child Sexual Abuse Material; Orders Ads Stopped", "category": "polity", "category_name": "Polity & Governance", "summary": "The Indian government issued a strict notice to Instagram (Meta) over the presence of child sexual abuse content (CSAM) on the platform, ordering it to immediately stop running advertisements until the matter is addressed. The Centre sought a response from the platform under India's IT Rules, 2021, which mandate intermediaries to proactively remove such content. This action reflects India's growing assertiveness in regulating social media platforms under the IT Act and intermediary liability framework. Child safety online is a priority regulatory area under the Digital India framework.", "exam_angle": "IT Act, 2000 and IT Rules 2021 (intermediary liability, content regulation) are direct GS Paper 2 (Polity/Governance) topics. Government's regulatory powers over social media platforms and CSAM provisions are frequently examined.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Platform targeted: Instagram (Meta)", "Action: Centre issued notice; ordered immediate stoppage of advertisements", "Legal basis: IT Rules 2021 (intermediary liability framework)", "Issue: Child Sexual Abuse Material (CSAM) found on platform"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Indian Naval Ships Conclude Successful Port Visit to Singapore", "category": "defence", "category_name": "Defence & Security", "summary": "Indian Naval Ships successfully concluded a port visit to Singapore, strengthening maritime ties between India and one of its key partners in Southeast Asia. Naval port visits are a key component of India's maritime diplomacy and reflect the growing India-Singapore strategic partnership. Singapore is a critical node in India's Act East Policy and the Indo-Pacific strategy, given its location at the Strait of Malacca. Such visits typically involve joint exercises, high-level meetings, and goodwill exchanges.", "exam_angle": "India's maritime diplomacy, Act East Policy, and naval engagement in the Indo-Pacific are core GS Paper 2 (IR) and GS Paper 3 (Defence) topics. Singapore's strategic location (Strait of Malacca) is frequently referenced.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Indian Naval Ships completed port visit to Singapore", "Strategic significance: Singapore located at Strait of Malacca — key chokepoint", "Context: Part of India's maritime diplomacy and Act East Policy", "Source: PIB (official government release)"], "source": "PIB", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Trump-Putin 90-Minute Call on July 4; Trump Repositions as Ukraine-Russia Peace Mediator", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump held a 90-minute telephone call with Russian President Vladimir Putin on July 4, 2026, which Moscow described as 'businesslike.' Trump offered to help Putin find a deal with Ukraine and also spoke separately with Ukrainian President Zelenskyy, repositioning himself as a peace mediator in the ongoing Russia-Ukraine conflict. The diplomatic development signals a potential shift in US engagement with the war. Trump also spoke with Israeli PM Netanyahu separately, agreeing to meet soon.", "exam_angle": "The Russia-Ukraine conflict's geopolitical dimensions and evolving US foreign policy are key GS Paper 2 (IR) topics. US mediation efforts, NATO dynamics, and India's neutral stance connect to several UPSC themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Trump-Putin call: 90-minute call on July 4, 2026; described as 'businesslike' by Moscow", "Trump offer: To mediate peace between Russia and Ukraine", "Also spoke with: Ukrainian President Zelenskyy", "Significance: Marks potential US re-engagement as mediator in Russia-Ukraine war"], "source": "Reuters", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Iran's Supreme Leader Ali Khamenei Dies; Funeral Held in Tehran, Successor Mojtaba Absent", "category": "ir", "category_name": "International Relations", "summary": "Iran's Supreme Leader Ali Khamenei passed away and his funeral was held in Tehran, attended by millions. His son Mojtaba Khamenei, widely speculated as a possible successor, was conspicuously absent from the funeral, raising questions about succession dynamics. Khamenei had held the position of Supreme Leader since 1989. The Supreme Leader is the highest authority in Iran under the concept of Velayat-e-Faqih (Guardianship of the Islamic Jurist), wielding ultimate power over all state institutions.", "exam_angle": "Iran's political system (Supreme Leader, Guardian Council, Velayat-e-Faqih), India-Iran relations, and West Asia geopolitics are GS Paper 2 (IR) topics. Succession in Iran has implications for nuclear negotiations and regional stability.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Deceased: Ali Khamenei — Iran's Supreme Leader since 1989", "Funeral held in Tehran; son Mojtaba Khamenei (possible successor) was absent", "Iran's governance: Supreme Leader holds highest authority under Velayat-e-Faqih", "Geopolitical implication: Succession uncertainty affects Iran nuclear deal talks and regional stability"], "source": "NDTV", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "IMD Issues Heavy Monsoon Warning; Monsoon Arrives in Delhi, Red Alert in Mumbai", "category": "environment", "category_name": "Environment & Ecology", "summary": "The India Meteorological Department (IMD) warned of intense monsoon activity with heavy rainfall expected across large parts of India. The monsoon officially arrived in Delhi, though rainfall was initially below expectations in some areas. Mumbai was placed under a red alert as heavy rains of over 200 mm in 12 hours caused flooding, disrupted local train services, and temporarily halted airport runway operations. Pune also reported waterlogging and two landslides due to intense rainfall.", "exam_angle": "IMD's alert system (colour-coded: green/yellow/orange/red), monsoon arrival, and rainfall classification are standard GS Paper 1 (Geography) and GS Paper 3 (Disaster Management) topics. Red alert thresholds and IMD's role are frequently asked.", "gs_paper": "GS Paper 1 (Geography)", "key_facts": ["IMD issued red alert for Mumbai; 200 mm rain recorded in 12 hours", "Monsoon officially arrived in Delhi (July 2026)", "Mumbai: Airport runway operations halted for an hour; train services disrupted", "Red alert criteria: Extremely heavy rainfall (>204.4 mm in 24 hours)"], "source": "Hindustan Times", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Prashant Kishor to Contest Bankipur Assembly By-Election on Jan Suraaj Party Ticket", "category": "persons", "category_name": "Persons & Awards in News", "summary": "Political strategist-turned-activist Prashant Kishor will make his electoral debut by contesting the Bankipur assembly by-election in Bihar on the Jan Suraaj Party ticket. Jan Suraaj, launched by Kishor in Bihar, aims to bring systemic change to the state's governance. The Bankipur constituency is located in Patna district and is considered a high-profile seat. This marks a significant transition for Kishor from election management to direct political participation.", "exam_angle": "Persons in News: Prashant Kishor's transition from political strategist to contesting politician is noteworthy. Jan Suraaj Party and Bihar political landscape may feature in State PSC exams. Connects to electoral politics and political parties.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Prashant Kishor: Contesting Bankipur assembly by-election, Bihar", "Party: Jan Suraaj Party (founded by Prashant Kishor)", "Constituency: Bankipur, Patna district, Bihar", "Significance: First electoral contest for Kishor after career as political strategist"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "World Bank Report Reveals Pakistan's Stark Fiscal Faultlines", "category": "reports", "category_name": "Reports & Indices", "summary": "A World Bank report highlighted severe fiscal vulnerabilities in Pakistan, revealing that public money and resources are disproportionately accessible as a 'privilege' rather than a universal right. The report pointed to structural issues including high debt burden, energy sector circular debt, low tax-to-GDP ratio, and inefficient public spending. Pakistan has been under an IMF bailout programme and continues to face macroeconomic instability. The findings are significant for understanding India's neighbourhood security and economic environment.", "exam_angle": "World Bank reports and Pakistan's fiscal health are relevant for GS Paper 2 (IR/India's neighbourhood) and GS Paper 3 (Economy). Understanding Pakistan's economic vulnerabilities is useful for questions on South Asian geopolitics.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Report: World Bank report on Pakistan's fiscal health", "Key finding: Public money in Pakistan accessible as 'privilege', not universal right", "Issues: High debt, energy circular debt, low tax-to-GDP ratio", "Context: Pakistan under IMF bailout programme; ongoing macroeconomic crisis"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Gwadar Port: Pakistan's Chinese-Backed Facility Faces Repeated Attacks by Baloch Militants", "category": "ir", "category_name": "International Relations", "summary": "Gwadar port, the centrepiece of the China-Pakistan Economic Corridor (CPEC) in Pakistan's Balochistan province, has continued to face attacks from Baloch separatist groups who view Chinese involvement as exploitative of local resources. The port is strategically significant as it provides China access to the Arabian Sea, bypassing the Strait of Malacca. India has consistently raised concerns about CPEC as it passes through Pakistan-Occupied Kashmir (PoK). The attacks reflect persistent instability in Balochistan and opposition to Chinese economic projects.", "exam_angle": "Gwadar port and CPEC are among the most frequently tested IR topics in UPSC, connecting to India-China-Pakistan triangle, BRI, and India's strategic concerns. The Strait of Malacca bypass rationale is a key exam fact.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Gwadar: Deep-sea port in Balochistan, Pakistan — centrepiece of CPEC", "CPEC: China-Pakistan Economic Corridor; part of China's Belt and Road Initiative (BRI)", "Strategic value for China: Access to Arabian Sea, bypasses Strait of Malacca", "India's objection: CPEC passes through Pakistan-Occupied Kashmir (PoK)"], "source": "NDTV", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "MY Bharat Platform: Connecting Digital India with India's Youth", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "The MY Bharat (Mera Yuva Bharat) platform, India's national digital platform for youth engagement, is bridging the gap between Digital India initiatives and young citizens. Launched in October 2023 under the Ministry of Youth Affairs and Sports, MY Bharat facilitates volunteerism, skill development, and youth participation in governance. The platform serves as a one-stop digital ecosystem for youth-centric programmes including internships, mentorship, and community service. PIB highlighted its role in creating active, engaged youth citizens.", "exam_angle": "MY Bharat (Mera Yuva Bharat) — launched on October 31, 2023 — is a frequently tested government scheme. Questions on its nodal ministry, objectives, and linkage to NEP 2020 and Digital India appear in Prelims.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Scheme: MY Bharat (Mera Yuva Bharat) — national youth digital platform", "Launched: October 31, 2023 (National Unity Day)", "Nodal Ministry: Ministry of Youth Affairs and Sports", "Objective: Facilitate youth volunteerism, skill development, and civic engagement digitally"], "source": "PIB", "day": "2026-07-05", "day_label": "05 Jul"}], "categories": [{"id": "polity", "name": "Polity & Governance"}, {"id": "economy", "name": "Economy & Banking"}, {"id": "ir", "name": "International Relations"}, {"id": "environment", "name": "Environment & Ecology"}, {"id": "scitech", "name": "Science & Technology"}, {"id": "schemes", "name": "Govt Schemes & Policies"}, {"id": "defence", "name": "Defence & Security"}, {"id": "reports", "name": "Reports & Indices"}, {"id": "persons", "name": "Persons & Awards in News"}, {"id": "places", "name": "Places in News"}, {"id": "culture", "name": "Art & Culture"}]};